INSERT INTO recipe_instructions (id, recipe_id, step_number, instruction_text, estimated_time) VALUES

-- Nasi Gudeg Yogyakarta instructions
('850e8400-e29b-41d4-a716-446655440001', '650e8400-e29b-41d4-a716-446655440001', 1, 'Potong nangka muda menjadi potongan kecil, buang bijinya. Cuci bersih dan tiriskan.', '15 menit'),
('850e8400-e29b-41d4-a716-446655440002', '650e8400-e29b-41d4-a716-446655440001', 2, 'Haluskan bawang merah, bawang putih, dan kemiri. Tumis bumbu halus hingga harum.', '10 menit'),
('850e8400-e29b-41d4-a716-446655440003', '650e8400-e29b-41d4-a716-446655440001', 3, 'Masukkan nangka muda, aduk rata dengan bumbu. Tambahkan daun salam dan lengkuas.', '5 menit'),
('850e8400-e29b-41d4-a716-446655440004', '650e8400-e29b-41d4-a716-446655440001', 4, 'Tuang santan dan gula merah yang sudah disisir. Masak dengan api kecil sambil diaduk.', '2.5 jam'),
('850e8400-e29b-41d4-a716-446655440005', '650e8400-e29b-41d4-a716-446655440001', 5, 'Masak terus hingga kuah mengental dan nangka empuk. Koreksi rasa garam dan gula.', '30 menit'),
('850e8400-e29b-41d4-a716-446655440006', '650e8400-e29b-41d4-a716-446655440001', 6, 'Sajikan gudeg dengan nasi putih, ayam, telur, dan sambal krecek.', '5 menit'),

-- Rendang Daging Sapi instructions
('850e8400-e29b-41d4-a716-446655440007', '650e8400-e29b-41d4-a716-446655440002', 1, 'Potong daging sapi menjadi kubus berukuran 3x3 cm. Cuci bersih dan tiriskan.', '15 menit'),
('850e8400-e29b-41d4-a716-446655440008', '650e8400-e29b-41d4-a716-446655440002', 2, 'Haluskan cabai merah, cabai keriting, bawang merah, bawang putih, jahe, dan lengkuas.', '20 menit'),
('850e8400-e29b-41d4-a716-446655440009', '650e8400-e29b-41d4-a716-446655440002', 3, 'Tumis bumbu halus hingga harum dan matang. Masukkan serai dan daun jeruk.', '10 menit'),
('850e8400-e29b-41d4-a716-446655440010', '650e8400-e29b-41d4-a716-446655440002', 4, 'Masukkan daging sapi, aduk rata hingga daging berubah warna.', '15 menit'),
('850e8400-e29b-41d4-a716-446655440011', '650e8400-e29b-41d4-a716-446655440002', 5, 'Tuang santan, masak dengan api sedang sambil terus diaduk agar tidak pecah.', '1 jam'),
('850e8400-e29b-41d4-a716-446655440012', '650e8400-e29b-41d4-a716-446655440002', 6, 'Kecilkan api, masak terus sambil diaduk hingga kuah mengental dan berminyak.', '2.5 jam'),
('850e8400-e29b-41d4-a716-446655440013', '650e8400-e29b-41d4-a716-446655440002', 7, 'Masak hingga rendang berwarna coklat kehitaman dan bumbu meresap sempurna.', '45 menit'),

-- Gado-gado Jakarta instructions
('850e8400-e29b-41d4-a716-446655440014', '650e8400-e29b-41d4-a716-446655440003', 1, 'Rebus telur hingga matang, kupas dan belah dua. Sisihkan.', '10 menit'),
('850e8400-e29b-41d4-a716-446655440015', '650e8400-e29b-41d4-a716-446655440003', 2, 'Rebus kentang hingga empuk, potong-potong. Rebus kangkung dan tauge sebentar.', '15 menit'),
('850e8400-e29b-41d4-a716-446655440016', '650e8400-e29b-41d4-a716-446655440003', 3, 'Goreng tahu dan tempe hingga kuning keemasan. Potong-potong.', '10 menit'),
('850e8400-e29b-41d4-a716-446655440017', '650e8400-e29b-41d4-a716-446655440003', 4, 'Sangrai kacang tanah hingga matang, haluskan dengan bumbu gado-gado.', '15 menit'),
('850e8400-e29b-41d4-a716-446655440018', '650e8400-e29b-41d4-a716-446655440003', 5, 'Tata semua sayuran dan lauk di piring, siram dengan bumbu kacang.', '5 menit'),
('850e8400-e29b-41d4-a716-446655440019', '650e8400-e29b-41d4-a716-446655440003', 6, 'Taburi dengan kerupuk yang sudah digoreng. Sajikan segera.', '2 menit'),

-- Sate Ayam Madura instructions
('850e8400-e29b-41d4-a716-446655440020', '650e8400-e29b-41d4-a716-446655440004', 1, 'Potong daging ayam menjadi kubus kecil. Rendam dalam bumbu marinasi selama 2 jam.', '2 jam'),
('850e8400-e29b-41d4-a716-446655440021', '650e8400-e29b-41d4-a716-446655440004', 2, 'Tusuk daging ayam dengan tusuk sate, masing-masing 4-5 potong daging.', '15 menit'),
('850e8400-e29b-41d4-a716-446655440022', '650e8400-e29b-41d4-a716-446655440004', 3, 'Sangrai kacang tanah hingga matang, haluskan bersama bumbu kacang.', '15 menit'),
('850e8400-e29b-41d4-a716-446655440023', '650e8400-e29b-41d4-a716-446655440004', 4, 'Bakar sate di atas arang sambil dibolak-balik dan diolesi bumbu.', '20 menit'),
('850e8400-e29b-41d4-a716-446655440024', '650e8400-e29b-41d4-a716-446655440004', 5, 'Sajikan sate dengan bumbu kacang, lontong, dan acar timun.', '5 menit'),

-- Es Cendol instructions
('850e8400-e29b-41d4-a716-446655440025', '650e8400-e29b-41d4-a716-446655440013', 1, 'Rebus daun pandan hingga air berwarna hijau. Saring dan dinginkan.', '10 menit'),
('850e8400-e29b-41d4-a716-446655440026', '650e8400-e29b-41d4-a716-446655440013', 2, 'Campur tepung hunkwe dengan air pandan, aduk hingga tidak bergerindil.', '5 menit'),
('850e8400-e29b-41d4-a716-446655440027', '650e8400-e29b-41d4-a716-446655440013', 3, 'Masak adonan sambil diaduk hingga mengental dan transparan.', '10 menit'),
('850e8400-e29b-41d4-a716-446655440028', '650e8400-e29b-41d4-a716-446655440013', 4, 'Cetak cendol menggunakan cetakan khusus ke dalam air es.', '10 menit'),
('850e8400-e29b-41d4-a716-446655440029', '650e8400-e29b-41d4-a716-446655440013', 5, 'Rebus gula merah dengan sedikit air hingga larut. Dinginkan.', '8 menit'),
('850e8400-e29b-41d4-a716-446655440030', '650e8400-e29b-41d4-a716-446655440013', 6, 'Sajikan cendol dengan santan, sirup gula merah, dan es batu.', '2 menit');
